const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

class SecretsManagerClient {
  constructor() {
    this.client = new SecretsManager();
    this.cache = new Map();
    this.ttl = 300000; // 5 minutes cache
  }

  async getSecret(secretName) {
    const cacheKey = `secret:${secretName}`;
    const cached = this.cache.get(cacheKey);

    if (cached && Date.now() - cached.timestamp < this.ttl) {
      return cached.value;
    }

    try {
      const response = await this.client.getSecretValue({ SecretId: secretName });
      const secret = JSON.parse(response.SecretString);
      this.cache.set(cacheKey, { value: secret, timestamp: Date.now() });
      return secret;
