      if (!value && process.env.NODE_ENV === 'production') {
        throw new Error(`Critical secret ${secretName} not found in environment`);
      }
    }

    // Cache the value
    this.cache.set(secretName, { value, timestamp: Date.now() });

    return value;
  }

  // Add rotation support
  async rotateSecret(secretName, provider) {
    // Implementation for secret rotation
    // Would involve generating new credentials, updating the secret manager,
    // and gracefully updating the application's cached credentials
  }
}

module.exports = new SecretsManager();
```

#### 2. Add Environment Validation on Startup

```javascript
// add this validation to app.js or a separate config.js
const validateEnvironment = () => {
  const requiredEnvVars = ['JWT_SECRET', 'DATABASE_URL', 'SESSION_SECRET'];
  const optionalEnvVars = ['AWS_ACCESS_KEY_ID', 'STRIPE_SECRET_KEY'];

  // Check required environment variables
  const missingRequired = requiredEnvVars.filter(varName => !process.env[varName]);
  if (missingRequired.length > 0) {
    throw new Error(`Missing required environment variables: ${missingRequired.join(', ')}. ` +
                   'Application cannot start without these secrets. ' +
                   'Use a secrets manager for production deployments.');
  }

  // Validate secret strength
  const checkSecretStrength = (secretName, minStrength = 'medium') => {
    const secret = process.env[secretName];
    if (!secret) return true; // Already checked as required

    let requirements = { minLen: 16, hasUpper: true, hasLower: true, hasNumber: true, hasSymbol: true };
    if (minStrength === 'low') requirements = { minLen: 8 };
    if (minStrength === 'high') requirements = { minLen: 32, hasUpper: true, hasLower: true, hasNumber: true, hasSymbol: true };

    if (secret.length < requirements.minLen) {
      throw new Error(`${secretName} must be at least ${requirements.minLen} characters`);
    }

    return true;
  };

  // Validate JWT_SECRET strength
  checkSecretStrength('JWT_SECRET', 'high');

  // Validate SESSION_SECRET strength  
  checkSecretStrength('SESSION_SECRET', 'high');

  // Validate DATABASE_URL includes credentials (not just connection string)
  if (process.env.DATABASE_URL) {
    const url = new URL(process.env.DATABASE_URL);
    if (!url.username || !url.password) {
      throw new Error('DATABASE_URL must include username and password in the URL');
    }
  }

  console.log('Environment validation passed for all required secrets');
};

// Call validation early in application startup
try {
  validateEnvironment();
} catch (error) {
  console.error('Environment validation failed:', error.message);
  process.exit(1);
}
```

#### 3. Implement Secrets Masking in Logs

```javascript
// Add this to your logging configuration
const maskSecrets = (message) => {
  const secretsToMask = [
    { name: 'JWT_SECRET', pattern: /JWT_SECRET=([^&\s]+)/g },
    { name: 'DATABASE_URL', pattern: /DATABASE_URL=([^&\s]+)/g },
    { name: 'AWS_SECRET_ACCESS_KEY', pattern: /AWS_SECRET_ACCESS_KEY=([^&\s]+)/g },
    { name: 'STRIPE_SECRET_KEY', pattern: /STRIPE_SECRET_KEY=([^&\s]+)/g },
    { name: 'ANTHROPIC_API_KEY', pattern: /ANTHROPIC_API_KEY=([^&\s]+)/g },
  ];

  let maskedMessage = message;

  for (const secret of secretsToMask) {
    if (process.env[secret.name]) {
      // Only mask the first 4 characters to allow for partial identification
      const value = process.env[secret.name];
      const maskedValue = value.length > 8 
        ? `${value.substring(0, 4)}${'*'.repeat(8)}${value.substring(value.length - 4)}`
        : `${'*'.repeat(value.length)}`;

      maskedMessage = maskedMessage.replace(secret.pattern, `${secret.name}=${maskedValue}`);
    }
  }

  return maskedMessage;
};

// Update your logging to mask secrets
const secureLogger = {
  info: (message, ...args) => {
    console.log(maskSecrets(message), ...args);
  },
  error: (message, ...args) => {
    console.error(maskSecrets(message), ...args);
  },
  warn: (message, ...args) => {
    console.warn(maskSecrets(message), ...args);
  }
};
```

#### 4. Add Secrets Rotation Support

```javascript
// secrets-rotation.js
const SecretsManager = require('./recommended-secrets-manager');

class SecretsRotator {
  constructor() {
    this.secretsManager = new SecretsManager();
    this.rotationSchedule = {
      JWT_SECRET: 90, // days
      SESSION_SECRET: 30, // days
      DATABASE_PASSWORD: 60, // days
    };
    this.rotationLog = [];
  }

  async checkRotations() {
    for (const [secretName, days] of Object.entries(this.rotationSchedule)) {
      await this.rotateIfExpired(secretName, days);
    }
  }

  async rotateIfExpired(secretName, maxAgeDays) {
    // In a real implementation, you would check when the secret was last rotated
    // For now, we'll rotate based on a simulated timestamp
    const lastRotation = this.rotationLog[secretName] || new Date(2020, 0, 1);
    const ageInDays = (Date.now() - lastRotation) / (1000 * 60 * 60 * 24);

    if (ageInDays > maxAgeDays) {
      secureLogger.info(`Rotating ${secretName} (age: ${Math.round(ageInDays)} days)`);
      await this.secretsManager.rotateSecret(secretName, process.env.SECRET_MANAGER_PROVIDER);

      // In a production system, you would implement a graceful transition
      // where old and new secrets are both valid for a period of time

      this.rotationLog[secretName] = new Date();
    }
  }

  // Schedule rotation checks every 24 hours
  startScheduledRotations() {
    this.checkRotations(); // Check immediately on startup
    setInterval(() => this.checkRotations(), 24 * 60 * 60 * 1000);
  }
}

module.exports = SecretsRotator;
```

### Cloud-Native Recommendations

Depending on your deployment environment:

1. **AWS**: Use AWS Secrets Manager or Parameter Store
2. **Azure**: Use Azure Key Vault
3. **Google Cloud**: Use Google Cloud Secret Manager
4. **Heroku**: Use Heroku Config Vars
5. **Docker/Kubernetes**: Use Docker Secrets or Kubernetes Secrets

### Development vs Production Separation

Ensure your development and production environments have completely separate secrets:

```javascript
// config/index.js
const isDevelopment = process.env.NODE_ENV === 'development';
const isLoadingTest = process.argv.some(arg => arg.includes('.test'));

const config = {
  secrets: {
    jwtSecret: process.env.JWT_SECRET || (isDevelopment && 'development-only-secret'),
    sessionSecret: process.env.SESSION_SECRET || (isDevelopment && 'development-only-session'),
    // NEVER use default secrets in production
  },
  database: {
    url: process.env.DATABASE_URL || 'postgresql://postgres:password@localhost:5432/app_db',
  },
};

// Prevent dangerous defaults in production
if (!isDevelopment && !isLoadingTest) {
  if (config.secrets.jwtSecret && config.secrets.jwtSecret.includes('development')) {
    throw new Error('JWT_SECRET cannot use development value in production');
  }

  if (config.database.url.includes('localhost') && process.env.DATABASE_URL !== config.database.url) {
    throw new Error('Production database cannot connect to localhost');
  }
}

module.exports = config;
```

#### 5. Implement Secret Access Auditing

```javascript
// secret-access-logger.js
const fs = require('fs');
const path = require('path');

class SecretAccessLogger {
  constructor() {
    this.accessLogPath = path.join(__dirname, 'logs/secret-access.log');
  }

  logAccess(secretName, accessedBy, timestamp = new Date()) {
    const logEntry = {
      timestamp: timestamp.toISOString(),
      secretName: secretName,
      accessedBy: accessedBy,
      success: true,
    };

    // Log to file
    try {
      const logLine = JSON.stringify(logEntry) + '\n';
      fs.appendFileSync(this.accessLogPath, logLine);
    } catch (error) {
      console.error('Failed to log secret access:', error.message);
    }

    // If secret access is sensitive, also log to console
    if (['JWT_SECRET', 'DATABASE_URL'].includes(secretName)) {
      console.log(`[${timestamp.toISOString()}] Secret "${secretName}" accessed by "${accessedBy}"`);
    }
  }
}

module.exports = new SecretAccessLogger();
```

