  'SELECT * FROM users WHERE email = $1', 
  [userEmail]
);
```

### 2. Missing Authentication and Authorization

**Issue**: The application has no authentication or authorization mechanism. All endpoints are publicly accessible, and there's no role-based access control (RBAC) to enforce the role checks mentioned in comments.

**Recommendation**: Implement authentication middleware (JWT or session-based) and authorization middleware:

```javascript
// Authentication middleware example
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) return res.status(401).json({ error: 'Access token required' });

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

// Authorization middleware example
const requireRole = (allowedRoles) => {
  return (req, res, next) => {
    if (!req.user || !allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

