/**
 * Secrets Management Configuration
 * 
 * This module handles secure loading and validation of application secrets.
 * In production, secrets should be loaded from:
 * - Environment variables (recommended for containerized deployments)
 * - AWS Secrets Manager (recommended for AWS deployments)
 * - HashiCorp Vault (recommended for enterprise environments)
 * - Azure Key Vault (recommended for Azure deployments)
 * - Google Cloud Secret Manager (recommended for GCP deployments)
 */

import dotenv from 'dotenv';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

/**
 * Load environment variables from .env file
 * Only loads in non-production environments for security
 */
function loadDotEnv() {
  // Skip loading .env in production (secrets should already be in environment)
  if (process.env.NODE_ENV === 'production') {
    console.log('ℹ️  Running in production mode. Using environment variables only.');
    return;
  }

  // Try to load .env file
  try {
    const envPath = path.resolve(__dirname, '../.env');
    const result = dotenv.config({ path: envPath });

    if (result.error) {
      console.warn('⚠️  .env file not found. Using only environment variables.');
    } else {
      console.log(`✓ Loaded secrets from: ${envPath}`);
    }
  } catch (error) {
    console.warn('⚠️  Error loading .env file:', error.message);
  }
}

/**
 * Validate required secrets
 * Throws error if critical secrets are missing
 */
function validateSecrets() {
  const errors = [];

  // Critical secrets for authentication
  if (!process.env.SESSION_SECRET) {
    errors.push('SESSION_SECRET is required. Generate with: openssl rand -hex 32');
  }

  // Database credentials (if using database)
  if (!process.env.DATABASE_URL) {
    console.warn('⚠️  DATABASE_URL not set. Database functionality will be unavailable.');
  }

  // External API keys (optional but recommended)
  if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
    console.warn('⚠️  AWS credentials not set. AWS integration will be unavailable.');
  }

  if (errors.length > 0) {
    console.error('❌ Missing required secrets:');
    errors.forEach(error => console.error(`   - ${error}`));
    process.exit(1);
  }
}

/**
 * Mask sensitive values for safe logging
 */
function maskSecret(value) {
  if (!value || typeof value !== 'string') return '[unset]';
  if (value.length < 8) return '[short]';
  return value.substring(0, 4) + '•'.repeat(6) + value.substring(value.length - 4);
}

/**
 * Get secrets with logging
 * Use this function instead of direct process.env access
 */
export function getSecret(name, options = {}) {
  const value = process.env[name];

  if (value === undefined && options.required !== false) {
    console.warn(`⚠️  Secret "${name}" is not set`);
  }

  // Log at debug level (only if DEBUG is enabled)
  if (process.env.DEBUG_SECRETS === 'true') {
    console.debug(`🔒 Secret "${name}" loaded: ${maskSecret(value)}`);
  }

  return value;
}

/**
 * Configuration object for secure secret access
 */
export const config = {
  // Authentication
  sessionSecret: getSecret('SESSION_SECRET', { required: true }),

  // Database
  databaseUrl: getSecret('DATABASE_URL'),

  // AWS
  awsAccessKeyId: getSecret('AWS_ACCESS_KEY_ID'),
  awsSecretAccessKey: getSecret('AWS_SECRET_ACCESS_KEY'),
  awsRegion: getSecret('AWS_REGION', { default: 'us-east-1' }),

  // External APIs
  anthropicApiKey: getSecret('ANTHROPIC_API_KEY'),
  stripeSecretKey: getSecret('STRIPE_SECRET_KEY'),
  logfireToken: getSecret('LOGFIRE_TOKEN'),
};

/**
 * Initialize secrets module
 */
export function initSecrets() {
  loadDotEnv();
  validateSecrets();

  console.log('✅ Secrets module initialized');
  console.log('ℹ️  Use getSecret() or config object to access secrets');

  // Log a masked version of session secret for verification
  console.log(`🔒 Session secret configured: ${maskSecret(config.sessionSecret)}`);

  return config;
}

/**
 * Utility: Generate a secure random string
 */
export function generateSecureSecret(length = 32) {
  const crypto = await import('crypto');
  return crypto.randomBytes(length).toString('hex');
}

export default initSecrets();

