    // Mock database lookup
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin', password: 'hashed_password_here' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user', password: 'hashed_password_here' },
    ];
    return users.find(user => user.email.toLowerCase() === email.toLowerCase());
